/*==========================================================================*/

// This status avoids sending a D2D command multiple times if many instances call cmd_q_insert(IGN...)
// This was not a problem before lib.status was created, because only 1 instance ever called d2d_tx.
// -1 = ign unknown (initial state - don't make assumptions)
//  0 = ign off
//  1 = ign on
static SInt8 status_ign = -1;

void bus_status_notify_input_ignition_off (void *arg)
{
	if (status_ign != 0) 
	{
		d2d_tx(SET_IGN_OFF);
		timeout_start(d2d_delay_timeout);
	}
	status_ign = 0;
}

//--------------------------------------------------------------------------//

void bus_status_notify_input_ignition_on (void *arg)
{
	if (status_ign != 1) 
	{
		d2d_tx(SET_IGN_ON);
	}
	status_ign = 1;
}

